-- Account service schema: product catalogue, accounts, status history and the event outbox.
-- Identifiers are UUIDv7 generated by the application. Cross-service references (customer_id, branch_code, the
-- *_by user ids) are plain values: there are no foreign keys to other services' databases.
-- Balances are a read-model of the Ledger (the source of truth); they only change through balance snapshots.

create sequence account_no_seq start with 1000000000 increment by 1;

create table account_products
(
    id           uuid primary key,
    code         varchar(30)    not null,
    name         varchar(150)   not null,
    account_type varchar(20)    not null,
    min_balance  numeric(19, 2) not null default 0,
    active       boolean        not null default true,
    created_at   timestamptz    not null default now(),
    updated_at   timestamptz    not null default now(),
    created_by   uuid,
    updated_by   uuid,
    version      bigint         not null default 0,
    constraint account_products_code_key unique (code),
    constraint account_products_type_chk check (account_type in ('SAVINGS', 'CURRENT')),
    constraint account_products_min_balance_chk check (min_balance >= 0)
);

create table accounts
(
    id                uuid primary key,
    account_no        varchar(30)    not null,
    customer_id       uuid           not null,
    branch_code       varchar(20)    not null,
    product_id        uuid           not null references account_products (id),
    currency          char(3)        not null,
    status            varchar(20)    not null default 'ACTIVE',
    ledger_balance    numeric(19, 2) not null default 0,
    available_balance numeric(19, 2) not null default 0,
    -- Ledger's monotonic sequence for the last applied snapshot; older or duplicate snapshots are ignored.
    balance_version   bigint         not null default 0,
    balance_as_of     timestamptz    not null default now(),
    opened_at         timestamptz    not null default now(),
    closed_at         timestamptz,
    created_at        timestamptz    not null default now(),
    updated_at        timestamptz    not null default now(),
    created_by        uuid,
    updated_by        uuid,
    version           bigint         not null default 0,
    constraint accounts_account_no_key unique (account_no),
    constraint accounts_status_chk check (status in ('PENDING', 'ACTIVE', 'FROZEN', 'CLOSED')),
    constraint accounts_currency_chk check (currency ~ '^[A-Z]{3}$'),
    constraint accounts_balances_chk check (ledger_balance >= 0 and available_balance >= 0),
    constraint accounts_closed_chk check ((status = 'CLOSED') = (closed_at is not null))
);

-- "All accounts of a customer" (customer 360 view) with an optional status filter.
create index accounts_customer_status_idx on accounts (customer_id, status);
-- Branch-scoped, newest-first listing (keyset-friendly: ties broken by id); the status variant serves filtered lists.
create index accounts_branch_created_idx on accounts (branch_code, created_at desc, id);
create index accounts_branch_status_created_idx on accounts (branch_code, status, created_at desc, id);
-- Unscoped listing for cross-branch roles (ADMIN, AUDITOR).
create index accounts_created_idx on accounts (created_at desc, id);
-- Prefix search ("starts with") must work regardless of the database collation.
create index accounts_account_no_prefix_idx on accounts (account_no varchar_pattern_ops);

-- Append-only audit trail of account status changes; previous_status is null for the opening entry.
create table account_status_history
(
    id              uuid primary key,
    account_id      uuid         not null references accounts (id),
    previous_status varchar(20),
    new_status      varchar(20)  not null,
    reason          varchar(500) not null,
    changed_by      uuid         not null,
    changed_at      timestamptz  not null default now(),
    correlation_id  varchar(64),
    constraint account_status_history_change_chk check (previous_status is null or previous_status <> new_status)
);

create index account_status_history_account_idx on account_status_history (account_id, changed_at desc, id);

-- Transactional outbox (ADR-006): rows are written in the same transaction as the business change.
-- A publisher that relays them to the broker is a later step; published_at stays null until then.
create table outbox_events
(
    id             uuid primary key,
    aggregate_type varchar(50)  not null,
    aggregate_id   uuid         not null,
    event_type     varchar(100) not null,
    payload        jsonb        not null,
    correlation_id varchar(64),
    created_at     timestamptz  not null default now(),
    published_at   timestamptz
);

create index outbox_events_unpublished_idx on outbox_events (created_at) where published_at is null;
